#define LPUART_INSTANCE LPUART1

void BOARD_InitLPUARTClock(void)
{
    CLOCK_EnableClock(kCLOCK_Lpuart1);

    clock_root_config_t clockRootCfg = {
        .clockRoot = kCLOCK_Root_Lpuart1,
        .preDivider = 0,
        .divider = 3
    };
    CLOCK_SetRootClock(&clockRootCfg);
}

void BOARD_InitLPUARTPins(void)
{
    // Configure RX pin (GPIO_AD_24)
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_24_LPUART1_RX, 0);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_24_LPUART1_RX,
        (kIOMUXC_MuxModeAlt3 | kIOMUXC_PullUp | kIOMUXC_PadSpeed100FS));

    // Configure TX pin (GPIO_AD_25)
    IOMUXC_SetPinMux(IOMUXC_GPIO_AD_25_LPUART1_TX, 0);
    IOMUXC_SetPinConfig(IOMUXC_GPIO_AD_25_LPUART1_TX,
        (kIOMUXC_MuxModeAlt3 | kIOMUXC_PullUp | kIOMUXC_PadSpeed100FS));
}

int main(void)
{
    lpuart_handle_t lpuartHandle;
    lpuart_config_t lpuartConfig;

    // Initialize clock
    BOARD_InitLPUARTClock();

    // Initialize pins
    BOARD_InitLPUARTPins();

    // Get default configuration
    LPUART_GetDefaultConfig(&lpuartConfig);
    lpuartConfig.baudRate_Bps = 115200;
    lpuartConfig.parityMode = kLPUART_ParityDisabled;
    lpuartConfig.stopBitCount = kLPUART_OneStopBit;
    lpuartConfig.dataBitsCount = kLPUART_EightDataBits;

    // Initialize LPUART
    LPUART_Init(LPUART_INSTANCE, &lpuartConfig, CLOCK_GetFreq(kCLOCK_IrCs));

